extends Area2D

var damage:= 30
var damage_enemies:=true
var direction:= Vector2.RIGHT
var SPEED:= 0
var ignore_body: Node2D = null
var currentTimeFactor := 1.0

var onHoverScaleFactor := 1.25
var slowDownTimeFactor := 0.1
var isAffectedBy := 0

@onready var sels: Sprite2D = $select_sprite
@onready var mc: Area2D = $mouseCollider

func _ready() -> void:
	add_to_group("selectable")
	body_entered.connect(_on_body_entered)
	mc.input_event.connect(_on_input_event)
	mc.mouse_entered.connect(_on_mouse_entered)
	mc.mouse_exited.connect(_on_mouse_exited)
	get_tree().create_timer(30.0).timeout.connect(queue_free)
	if Global.powerMode:
		set_speed(Global.ULTRAINSTINCT_SLOWDOWN)
	toggle_sprite()

func toggle_sprite() -> void:
	sels.visible = Global.powerMode

func set_speed(mult: float) -> void:
	currentTimeFactor *= mult

func _physics_process(delta: float) -> void:
	rotation = direction.angle()
	global_position += direction * delta * currentTimeFactor * SPEED

func _on_body_entered(body: Node2D) -> void:
	if body == ignore_body:
		return
	if (body.is_in_group("Player") or damage_enemies) and body.has_method("take_damage"):
		body.take_damage(damage)
	queue_free()

func _on_mouse_entered() -> void:
	sels.scale *= onHoverScaleFactor

func _on_mouse_exited() -> void:
	sels.scale /= onHoverScaleFactor

func _on_input_event(_viewport: Node, event: InputEvent, _shape_idx: int) -> void:
	if not Global.powerMode:
		return
	if event is InputEventMouseButton:
		if event.button_index == MOUSE_BUTTON_LEFT and event.pressed:
			Global.toggle_all()
			set_speed(slowDownTimeFactor)
			isAffectedBy += 1
			damage_enemies = true
			get_tree().create_timer(5.0).timeout.connect(func():
				if is_instance_valid(self):
					set_speed(1.0 / slowDownTimeFactor)
					isAffectedBy -= 1
			)

extends CharacterBody2D


@export var SPEED = 5.0
@export var JUMP_VELOCITY = -400.0
@export var MAX_HEALTH := 25
@export var MAX_VELOCITY := 80.0
@export var COUNTDOWN_HEIGHT := 60
@export var onHoverScaleFactor = 1.25
@export var slowDownTimeFactor = 0.1
@export var power := 2.0
@export var friction := 1.0
@export var max_drag := 50.0
@export var line : Line2D = null
@export var sels : Sprite2D = null
@export var mc : Area2D = null

@onready var tmrScene: PackedScene = preload("res://scenes/characters/timer_node.tscn")
@onready var healthBarScene: PackedScene = preload("res://scenes/characters/helpers/HealthBar.tscn")
@onready var health:= MAX_HEALTH

var currentTimeFactor := 1.0
var dragging := false
var drag_start := Vector2.ZERO
var drag_current := Vector2.ZERO

var isAffectedBy := 0
var isThrown := false
var is_grabbed := false
var _kill_counted := false
var _enemy_dead := false
const REF_GRAVITY: float = 980.0

func _ready() -> void:
	Global.enemy_count += 1
	set_physics_process(false)
	var mat := PhysicsMaterial.new()
	mat.friction = friction
	set("physics_material_override", mat)
	if line == null:
		line = $ShootDir
	if sels == null:
		sels = $select_sprite
	if mc == null:
		mc = $mouseCollider
	mc.input_event.connect(_on_mouse_collider_input_event)
	mc.mouse_entered.connect(_on_mouse_collider_mouse_entered)
	mc.mouse_exited.connect(_on_mouse_collider_mouse_exited)
	if Global.powerMode:
		currentTimeFactor = Global.ULTRAINSTINCT_SLOWDOWN
	var hb = healthBarScene.instantiate()
	hb.enemy = self
	hb.position = Vector2(0, -35)
	add_child(hb)


func toggle_sprite() -> void:
	sels.visible = Global.powerMode
	if not Global.powerMode and dragging:
		dragging = false
		mc.scale /= 20.0
		line.clear_points()

func CreateTimer(time: int, functi: Callable):
	var x = tmrScene.instantiate()
	x.time = time
	x.cb = functi 
	x.height = COUNTDOWN_HEIGHT
	add_child(x)
	x.global_position = global_position

func set_speed(mult: float) -> void:
	currentTimeFactor *= mult
	if mult < 1.0:
		velocity *= mult

func _gravity_compensation() -> float:
	var g = get_gravity().length()
	if g <= 0.0:
		return 1.0
	return sqrt(g / REF_GRAVITY)

func _on_death() -> void:
	if _enemy_dead:
		return
	_enemy_dead = true
	Global.kill_count += 1
	Global.enemy_count -= 1

func _on_mouse_collider_mouse_entered() -> void:
	sels.scale *= onHoverScaleFactor

func _on_mouse_collider_mouse_exited() -> void:
	sels.scale /= onHoverScaleFactor

func _tf() -> void:
	if currentTimeFactor < 1.0:
		if Global.powerMode:
			currentTimeFactor = Global.ULTRAINSTINCT_SLOWDOWN
		else:
			currentTimeFactor = 1.0
	isAffectedBy -= 1
	if dragging:
		dragging = false
		Global.toggle_all()
		mc.scale /= 20.0
		line.clear_points()

func take_damage(amount: int) -> void:
	health -= amount
	if health <= 0:
		_on_death()
		queue_free()

func throw() -> void:
	var drag = global_position - get_global_mouse_position()
	if drag.length() > max_drag:
		drag = drag.normalized() * max_drag
	var throw_power = power
	if currentTimeFactor >= 1.0:
		throw_power *= (1.0 / Global.ULTRAINSTINCT_SLOWDOWN)
	velocity += drag * throw_power * _gravity_compensation()
	currentTimeFactor = 1.0
	move_and_slide()
	isThrown = true
	set_physics_process(true)

func update_trajectory() -> void:
	line.clear_points()
	var drag = global_position - get_global_mouse_position()
	if drag.length() > max_drag:
		drag = drag.normalized() * max_drag
	var vel2 = (velocity + drag * power * _gravity_compensation()) * (1.0 / Global.ULTRAINSTINCT_SLOWDOWN)

	var simpos = Vector2.ZERO
	var step_dt = 0.25

	for i in range(15):
		line.add_point(simpos)
		vel2 += get_gravity() * step_dt
		simpos += vel2 * step_dt

func _on_mouse_collider_input_event(_viewport: Node, event: InputEvent, _shape_idx: int) -> void:
	if not Global.powerMode:
		return
	if event is InputEventMouseButton:
		if event.button_index == MOUSE_BUTTON_LEFT and event.pressed:
			if Global.elixir >= Global.enemy_freeze_elixir_cost:
				Global.elixir -= Global.enemy_freeze_elixir_cost
				Global.toggle_all()
				set_speed(slowDownTimeFactor)
				isAffectedBy += 1
				CreateTimer(5, Callable(self, "_tf"))
		elif event.button_index == MOUSE_BUTTON_RIGHT and (Global.player.global_position - global_position).length_squared() < (Global.throwDistance**2):
			if event.is_released() and dragging:
				Global.toggle_all()
				throw()
			elif event.pressed:
				if global_position.distance_squared_to(get_global_mouse_position()) < 576:
					mc.scale *= 20.0
					dragging = true
		else:
			if (!Input.is_mouse_button_pressed(MOUSE_BUTTON_RIGHT)) and (line.points.size() > 0):
				line.clear_points()
	elif event is InputEventMouseMotion and dragging:
		update_trajectory()

func _physics_process(delta: float) -> void:
	#animating shit
	if velocity.x > 0 || velocity.x < 0:
		animate('run')
	else:
		animate('idle')
	var tDelta = delta * currentTimeFactor
	if not is_on_floor():
		velocity += get_gravity() * tDelta 
		animate('jump')
	if isThrown && (is_on_ceiling() || is_on_floor() || is_on_wall()):
		isThrown = false
		animate('jump')
	move_and_slide()

func animate(_animation_name: String) -> void:
	pass

extends CanvasLayer

@export var next_scene: PackedScene
@export var options_scene: PackedScene

@onready var start_button: Button = $ColorRect/StartButton
@onready var how_to_play_button: Button = $ColorRect/HowToPlayButton
@onready var options_button: Button = $ColorRect/OptionsButton
@onready var quit_button: Button = $ColorRect/QuitButton
@onready var how_to_play_overlay: CanvasLayer = $HowToPlayOverlay

func _ready() -> void:
	visible = true
	start_button.pressed.connect(_on_start_button_pressed)
	how_to_play_button.pressed.connect(_on_how_to_play_button_pressed)
	options_button.pressed.connect(_on_options_button_pressed)
	quit_button.pressed.connect(_on_quit_button_pressed)
	how_to_play_overlay.closed.connect(_on_how_to_play_closed)

func _on_start_button_pressed() -> void:
	if next_scene:
		Global.start_level(next_scene)
	else:
		visible = false

func _on_how_to_play_button_pressed() -> void:
	_set_menu_buttons_disabled(true)
	how_to_play_overlay.open()

func _on_how_to_play_closed() -> void:
	_set_menu_buttons_disabled(false)

func _set_menu_buttons_disabled(is_disabled: bool) -> void:
	start_button.disabled = is_disabled
	how_to_play_button.disabled = is_disabled
	options_button.disabled = is_disabled
	quit_button.disabled = is_disabled

func _on_options_button_pressed() -> void:
	if options_scene:
		get_tree().paused = false
		get_tree().change_scene_to_packed(options_scene)
	else:
		print("Options button clicked!")

func _on_quit_button_pressed() -> void:
	get_tree().quit()

@tool
extends Control

@export var num_levels: int = 5:
	set(val):
		num_levels = max(1, val)
